#!/usr/bin/env python3
from pathlib import Path
import hashlib,json,datetime,sys
R=Path(__file__).resolve().parent
now=lambda:datetime.datetime.now(datetime.timezone.utc).isoformat().replace('+00:00','Z')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def write_once(p,x):
 with p.open('x') as f:f.write(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
 p.chmod(0o444)
def inventory(root,excluded):
 return {str(p.relative_to(root)):sha(p) for p in sorted(root.rglob('*')) if p.is_file() and str(p.relative_to(root)) not in excluded and '__pycache__' not in p.parts}
# Verify only the frozen Skill member paths; never open unrelated sealed assignments/cases.
gate=R.parent/'gates'/'tools.json';g=json.loads(gate.read_text());entries={k:v for k,v in g['members']['candidate-v8'].items() if k.startswith('candidate-v8/')};bad=[k for k,v in entries.items() if sha(R.parent/k)!=v]
if bad:raise RuntimeError('Frozen Skill changed: '+','.join(bad))
validation=json.loads((R/'validation-summary.json').read_text());integrity=json.loads((R/'delivery-integrity.json').read_text());authored=json.loads((R/'authored-at.json').read_text());end=now()
write_once(R/'FINAL-PHASES.json',{'actual_design_started_at':'2026-10-22T01:14:41Z','all_three_initial_proposals_authored_at':authored['actual_all_design_authored_at'],'actual_final_design_finished_at':end,'actual_contract_validation_started_at':validation['actual_validation_started_at'],'actual_contract_validation_finished_at':validation['actual_validation_finished_at'],'actual_delivery_integrity_checked_at':integrity['checked_at'],'sequence_note':'All three proposals existed before first compiler invocation; reference/document self-QA continued before final task sealing. Frozen typed rules, source values and policy stayed unchanged after locking. No candidate implementation existed or was inspected by this designer.','design_quality_approval':False,'next_phase':'Fresh independent design review before candidate implementation','native_sdk_invocations':0,'frozen_skill_files_verified':len(entries),'tools_gate_exact_sha256':sha(gate)})
for task in authored['tasks']:
 tid=task['id'];b=R/tid
 public=json.loads((b/'public'/'approval.json').read_text());private=json.loads((b/'private'/'approval.json').read_text())
 write_once(b/'seal.json',{'version':1,'task':tid,'domain':task['domain'],'component':task['component'],'interaction_structure':task['structure'],'proposal':'design-v1','status':'sealed_preimplementation_design_for_independent_review','actual_design_started_at':'2026-10-22T01:14:41Z','actual_design_finished_at':end,'actual_contract_validation_started_at':validation['actual_validation_started_at'],'actual_contract_validation_finished_at':validation['actual_validation_finished_at'],'actual_final_integrity_checked_at':integrity['checked_at'],'sealed_at':now(),'selected_per_case':{'states':7,'rules':14,'ledger_cells_per_platform':98,'required_cells_per_platform':81,'not_applicable_per_platform':17},'public_approval':public,'private_approval':private,'native_sdk_invocations':0,'independence':'No candidate implementation, historical business case or private assignment inspected. References and typed expected values authored independently.','design_quality_approval':False,'files_sha256':inventory(b,{'seal.json'}),'immutability':'Created with exclusive write; chmod0444. Further revisions require new directory and seal. Self digest is recorded in cohort seal.'})
write_once(R/'seal.json',{'version':1,'cohort':'atomic-forward-independent-design-v1','status':'sealed_preimplementation_design_for_fresh_independent_review','actual_design_started_at':'2026-10-22T01:14:41Z','actual_design_finished_at':end,'actual_contract_validation_started_at':validation['actual_validation_started_at'],'actual_contract_validation_finished_at':validation['actual_validation_finished_at'],'actual_delivery_integrity_checked_at':integrity['checked_at'],'sealed_at':now(),'tools_gate_exact_sha256':sha(gate),'tasks':{tid:sha(R/tid/'seal.json') for tid in ['T1','T2','T3']},'all_cases_platforms':18,'schema_compile_and_catalog':'18/18 accepted by unchanged frozen real CLIs','native_sdk_invocations':0,'design_quality_approval':False,'private_handling':'Only T*/public minus compiled is builder-facing. T*/private, root private, scripts/internal records and authoring-attempts are private to design/review staff until all public FINAL seals.','files_sha256':inventory(R,{'seal.json'}),'immutability':'Created with exclusive write; chmod0444. This file excludes its own digest by definition; parent records its exact SHA. No post-seal file additions/edits in this proposal.'})
print(json.dumps({'cohort_seal_sha256':sha(R/'seal.json'),'task_seals':{tid:sha(R/tid/'seal.json') for tid in ['T1','T2','T3']},'actual_design_finished_at':end,'cohort_files':len(json.loads((R/'seal.json').read_text())['files_sha256'])},indent=2))
